PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE products (
	id VARCHAR NOT NULL, 
	product_no INTEGER, 
	recorded_at DATETIME, 
	note TEXT, 
	takealot_url VARCHAR, 
	tsin VARCHAR, 
	product_name VARCHAR, 
	product_image_url VARCHAR, 
	product_image_path VARCHAR, 
	actual_sale_price_zar FLOAT, 
	fee_category VARCHAR, 
	fee_category_confirmed BOOLEAN, 
	fee_rate_range VARCHAR, 
	success_fee_rate FLOAT, 
	success_fee_cap FLOAT, 
	purchase_url VARCHAR, 
	sku VARCHAR, 
	chinese_product_name VARCHAR, 
	purchase_cost_cny FLOAT, 
	purchase_shipping_cny FLOAT, 
	purchase_quantity INTEGER, 
	length_mm FLOAT, 
	width_mm FLOAT, 
	height_mm FLOAT, 
	actual_weight_kg FLOAT, 
	packaging_cost_per_unit_cny FLOAT, 
	shipping_method VARCHAR, 
	inbound_listing_fee_cny FLOAT, 
	outbound_operation_fee_cny FLOAT, 
	last_mile_delivery_fee_cny FLOAT, 
	other_fee_cny FLOAT, 
	fulfillment_fee_zar FLOAT, 
	manual_domestic_forwarding_cny FLOAT, 
	manual_international_shipping_cny FLOAT, 
	manual_overseas_op_cost_cny FLOAT, 
	manual_success_fee_zar FLOAT, 
	manual_fulfillment_fee_zar FLOAT, 
	manual_total_cost_zar FLOAT, 
	volume_cbm FLOAT, 
	volumetric_weight_kg FLOAT, 
	chargeable_weight_kg FLOAT, 
	domestic_forwarding_cost_per_unit_cny FLOAT, 
	unit_product_cost_cny FLOAT, 
	international_shipping_per_unit_cny FLOAT, 
	cost_to_sa_warehouse_cny FLOAT, 
	cost_to_sa_warehouse_zar FLOAT, 
	overseas_warehouse_operation_cost_cny FLOAT, 
	overseas_warehouse_operation_cost_zar FLOAT, 
	success_fee_zar FLOAT, 
	official_total_cost_zar FLOAT, 
	total_cost_zar FLOAT, 
	profit_zar FLOAT, 
	profit_margin FLOAT, 
	minimum_price_at_20_margin FLOAT, 
	minimum_price_at_15_margin FLOAT, 
	link_status VARCHAR, 
	selection_status VARCHAR, 
	exchange_rate_used FLOAT, 
	fee_rate_used FLOAT, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE fee_categories (
	id VARCHAR NOT NULL, 
	name VARCHAR NOT NULL, 
	fee_rate_range VARCHAR, 
	success_fee_rate FLOAT NOT NULL, 
	active BOOLEAN, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE (name)
);
CREATE TABLE fee_mapping_rules (
	id VARCHAR NOT NULL, 
	takealot_category_pattern VARCHAR, 
	title_keyword_pattern VARCHAR, 
	fee_category VARCHAR NOT NULL, 
	priority INTEGER, 
	active BOOLEAN, 
	created_by_user BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE system_settings (
	id VARCHAR NOT NULL, 
	"key" VARCHAR NOT NULL, 
	value VARCHAR NOT NULL, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	UNIQUE ("key")
);
CREATE TABLE scrape_logs (
	id VARCHAR NOT NULL, 
	product_id VARCHAR NOT NULL, 
	original_url VARCHAR, 
	scrape_time DATETIME, 
	original_title VARCHAR, 
	original_price VARCHAR, 
	result VARCHAR, 
	error_message TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(product_id) REFERENCES products (id)
);
COMMIT;
